from django.db import migrations, models

PM_ROLE_KEYWORDS = ('manager', 'менеджер', 'руководитель')


def normalize_project_managers(apps, schema_editor):
    """
    Раньше роль участника записывалась то как 'MANAGER', то названием глобальной роли
    («Project Manager»). Права теперь завязаны на role == 'MANAGER', поэтому приводим
    данные к одному виду и гарантируем, что ответственный менеджер состоит в команде.
    """
    Project = apps.get_model('projects', 'Project')
    ProjectMember = apps.get_model('projects', 'ProjectMember')

    for member in ProjectMember.objects.exclude(role='MANAGER').select_related('role_ref'):
        names = [member.role or '', member.role_ref.name if member.role_ref_id else '']
        if any(kw in name.lower() for name in names for kw in PM_ROLE_KEYWORDS):
            member.role = 'MANAGER'
            member.save(update_fields=['role'])

    for project in Project.objects.exclude(manager__isnull=True):
        member, created = ProjectMember.objects.get_or_create(
            project=project, user_id=project.manager_id, defaults={'role': 'MANAGER'}
        )
        if not created and member.role != 'MANAGER':
            member.role = 'MANAGER'
            member.save(update_fields=['role'])


